j:jelly.g2:evaluate:
	var hasAccess=true;
	var	roleChecker = gs.getProperty('sn_res_shaper.show_rs_roles', '');
    if(!gs.nil(roleChecker)) {
		hasAccess=false;
		var roles= roleChecker.split(",");
		var len = roles.length;
		for (i = 0; i != len ; i++) {
			var roleName = roles[i].trim();
			if(gs.hasRole(roleName)) {
				hasAccess=true;
				break;
			}
		}
	}
	hasAccess;

