td.script:
function toggleTimeline(){
	var timeline = jQuery(".timelineContainer");
	var timelineBtn = jQuery('#timelineToggle');
	if(timelineBtn.hasClass("icon-chevron-down")){
		timeline.hide();
		timelineBtn.removeClass("icon-chevron-down").addClass("icon-chevron-right");
	}else{
		timeline.show();
		timelineBtn.removeClass("icon-chevron-right").addClass("icon-chevron-down");
	}
}

addAfterPageLoadedEvent(function(){
		var consumerSysId = "";
		if(g_form.getValue('consumer')){
			consumerSysId = "$[jvar_consumer]"; 
		}
		var rs_config= JSON.parse('$[jvar_res_config]');
		if(rs_config $[AMP]$[AMP] rs_config.isSuccess){
			jQuery(".timelineMainContainer").css('display','block');
			var sys_id = "${jvar_record_id}" || (window.g_form ? g_form.getUniqueValue() : "");
			var table_name = "${jvar_table}" || "${ref_parent}";
			var caller = "${jvar_caller}" ||consumerSysId || (window.g_form ? g_form.getValue('contact') || g_form.getValue('caller') || g_form.getValue('caller_id') : "");
			var reShaper = new ResolutionShaper(table_name, sys_id, caller, rs_config.config);
			reShaper.charting();
		}	else{
			if("${sysparm_media}"!="print")
				jQuery(".show-hide-info-message").css('display','block');
		}				
});
